local Blueprints=include("rhenium_contraption_blueprints/blueprints.lua");local S={HookPrefix="RheniumContraptionBlueprints",TimerName="RheniumContraptionBlueprints.Save"};local core,installed=nil,false;local player_rows,entity_rows={},{};local function find(rows,o)for _,r in ipairs(rows)do if r.object==o then return r end end end;local function validid(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")end;local function validrev(v)return type(v)=="number"and v>=1 and v%1==0 and v<math.huge end;local function xyz(v)return{x=v.x or 0,y=v.y or 0,z=v.z or 0}end;local function ep(v)if IsValid and IsValid(v)and v.EntIndex then return v:EntIndex()end;return type(v)=="table"and(v.Index or v.Entity or v[1])or v end
local function signatures(rows)local out={};for _,x in pairs(rows or{})do local a,b=ep(x.Ent1),ep(x.Ent2);if a==nil or b==nil or type(x.Type)~="string"then return nil end;a,b=tostring(a),tostring(b);if b<a then a,b=b,a end;out[#out+1]=x.Type.."|"..a.."|"..b end;table.sort(out);return out end
local function graph(c,listed)local left,right=signatures(c.Constraints),signatures(listed);if not left or not right or#left~=#right then return nil end;for i=1,#left do if left[i]~=right[i]then return nil end end;local g={entities={},constraints={}};for k,e in pairs(c.Entities or{})do g.entities[#g.entities+1]={source_id=tostring(k),class=e.Class or"prop_physics",model=e.Model,pos=xyz(e.Pos or Vector()),ang=xyz(e.Angle or Angle())}end;for _,x in pairs(c.Constraints or{})do g.constraints[#g.constraints+1]={type=x.Type,a=tostring(ep(x.Ent1)),b=tostring(ep(x.Ent2)),params={Bone1=x.Bone1 or 0,Bone2=x.Bone2 or 0,forcelimit=x.forcelimit or 0,nocollide=x.nocollide or false}}end;return g end
function S.Install(o)if installed then return S end;o=o or{};core=assert(Blueprints.new({state=o.state}));hook.Add("PlayerDisconnected",S.HookPrefix..".Disconnect",function(p)for i=#player_rows,1,-1 do if player_rows[i].object==p then table.remove(player_rows,i)end end end);hook.Add("EntityRemoved",S.HookPrefix..".Removed",function(e)for i=#entity_rows,1,-1 do if entity_rows[i].object==e then table.remove(entity_rows,i)end end end);timer.Create(S.TimerName,5,0,function()if core then core:save()end end);installed=true;return S end
function S.BindPlayer(p,id)if not installed or not IsValid(p)or not p:IsPlayer()or not validid(id)then return false end;player_rows[#player_rows+1]={object=p,id=id};return true end;function S.BindEntity(e,id,r)if not installed or not IsValid(e)or not validid(id)or not validrev(r)then return false end;entity_rows[#entity_rows+1]={object=e,id=id,revision=r};return true end
function S.Capture(p,root,n,rid,rev)local owner,b=find(player_rows,p),find(entity_rows,root);if not owner or not b or not IsValid(root)then return false,"unbound",{}end;if hook.Run("CanTool",p,{Entity=root},"duplicator")==false then return false,"permission_denied",{}end;local listed=constraint.GetTable(root);local copied=duplicator.Copy(root);if type(copied)~="table"or type(copied.Entities)~="table"or type(listed)~="table"then return false,"capture_failed",{}end;local g=graph(copied,listed);if not g then return false,"capture_failed",{}end;return core:capture(rid,owner.id,n,rev,g)end
local function tables(plan)local es,map={},{};for i,e in ipairs(plan.entities)do map[e.id]=i;es[i]={Class=e.class,Model=e.model,Pos=Vector(e.pos.x,e.pos.y,e.pos.z),Angle=Angle(e.ang.x,e.ang.y,e.ang.z),PhysicsObjects={[0]={Frozen=true}}}end;local cs={};for i,c in ipairs(plan.constraints)do local b1,b2=c.params.Bone1 or 0,c.params.Bone2 or 0;cs[i]={Type=c.type,Entity={{Index=map[c.a],Bone=b1},{Index=map[c.b],Bone=b2}},Bone1=b1,Bone2=b2,forcelimit=c.params.forcelimit or 0,nocollide=c.params.nocollide or false}end;return es,cs end
function S.Paste(p,n,target,rid,rev)local owner=find(player_rows,p);if not owner then return false,"unbound",{}end;if hook.Run("CanTool",p,{Entity=NULL},"duplicator")==false then return false,"permission_denied",{}end;local ok,c,plan=core:plan(rid,owner.id,n,rev,xyz(target));if not ok then return ok,c,plan end;local es,cs=tables(plan);local call,made,edges=pcall(duplicator.Paste,p,es,cs);made=made or{};edges=edges or{};local ne,nc=0,0;for _,e in pairs(made)do if IsValid(e)then ne=ne+1 end end;for _,e in pairs(edges)do if IsValid(e)then nc=nc+1 end end;if not call or ne~=#plan.entities or nc~=#plan.constraints then for _,e in pairs(edges)do if IsValid(e)then e:Remove()end end;for _,e in pairs(made)do if IsValid(e)then e:Remove()end end;return false,"paste_failed",{entities=0,constraints=0}end;undo.Create("Rhenium Contraption Blueprint");for _,e in pairs(made)do undo.AddEntity(e);cleanup.Add(p,"props",e)end;for _,e in pairs(edges)do undo.AddEntity(e)end;undo.SetPlayer(p);if undo.Finish()~=true then for _,e in pairs(edges)do if IsValid(e)then e:Remove()end end;for _,e in pairs(made)do if IsValid(e)then e:Remove()end end;return false,"undo_failed",{entities=0,constraints=0}end;core:record_paste(rid,{entities=ne,constraints=nc});return true,"pasted",{entities=made,constraints=edges,hash=plan.hash}end
function S.List(p)local x=find(player_rows,p);return x and core:list(x.id)or{}end;function S.Save()return core and core:save()end;function S.Shutdown()if installed then hook.Remove("PlayerDisconnected",S.HookPrefix..".Disconnect");hook.Remove("EntityRemoved",S.HookPrefix..".Removed");timer.Remove(S.TimerName);installed=false end;if core then core:shutdown()end;player_rows={};entity_rows={};return true,"shutdown"end;return S
